beam-search:
def beam_select(candidates, beam_width, alpha=1.0):
    ranked = sorted(enumerate(candidates), key=lambda pair: (-(pair[1][1] / (len(pair[1][0]) ** alpha)), pair[0]))
    return [candidate[0] for _, candidate in ranked[:beam_width]]

