def gqa_mapping(query_heads, kv_heads):
    if query_heads % kv_heads:
        raise ValueError("query_heads must be divisible by kv_heads")
    group_size = query_heads // kv_heads
    return [head // group_size for head in range(query_heads)]

grpo-clipped-loss:
import math

def grpo_surrogate(ratios, rewards, eps_clip=0.2, eps_std=1e-6):
    mean = sum(rewards) / len(rewards)
    std = math.sqrt(sum((r - mean) ** 2 for r in rewards) / len(rewards))
    advantages = [(r - mean) / (std + eps_std) for r in rewards]
    terms = []
    for ratio, advantage in zip(ratios, advantages):
        clipped = min(max(ratio, 1 - eps_clip), 1 + eps_clip)
        terms.append(min(ratio * advantage, clipped * advantage))
    return sum(terms) / len(terms)

infonce-loss:
import math

def infonce_loss(similarities, temperature=1.0):
    if temperature <= 0:
        raise ValueError("temperature must be positive")
    if not similarities:
        raise ValueError("batch must be non-empty")
    batch = len(similarities)
    if any(len(row) != batch for row in similarities):
        raise ValueError("similarities must be square")

    total = 0.0
    for i, row in enumerate(similarities):
        scaled = [value / temperature for value in row]
        maximum = max(scaled)
        logsumexp = maximum + math.log(sum(math.exp(value - maximum) for value in scaled))
        total += logsumexp - scaled[i]
    return total / batch

