def kv_cache_gib(
    layers,
    batch,
    tokens,
    kv_heads,
    head_dim,
    bytes_per_element,
):
    elements = 2 * layers * batch * tokens * kv_heads * head_dim
    return elements * bytes_per_element / (1024 ** 3)

kv-cache-update:
def append_kv_cache(cache_k, cache_v, new_k, new_v):
    if len(cache_k) != len(cache_v):
        raise ValueError("K/V cache length mismatch")
    if len(new_k) != len(new_v):
        raise ValueError("new K/V dimension mismatch")
    if cache_k and (len(cache_k[0]) != len(new_k) or len(cache_v[0]) != len(new_v)):
        raise ValueError("cache dimension mismatch")
    return [[*map(list, cache_k), list(new_k)], [*map(list, cache_v), list(new_v)]]

linear-warmup:
def warmup_lr(step, warmup_steps, peak_lr):
    if warmup_steps <= 0:
        return peak_lr
    return peak_lr * min(max(step, 0) / warmup_steps, 1.0)

