def multi_head_shape(batch, tokens, model_dim, heads):
    if model_dim % heads:
        raise ValueError("model_dim must be divisible by heads")
    return [batch, heads, tokens, model_dim // heads]

pass-at-k:
import math

def pass_at_k(n, c, k):
    if n - c < k:
        return 1.0
    return 1.0 - math.comb(n - c, k) / math.comb(n, k)

