import math

def reward_ranking_loss(chosen, rejected):
    value = rejected - chosen
    return max(value, 0.0) + math.log1p(math.exp(-abs(value)))

rotary-embedding:
def apply_rope(x, cos, sin):
    output = []
    for pair, (c, s) in enumerate(zip(cos, sin)):
        a, b = x[2 * pair], x[2 * pair + 1]
        output.extend([a * c - b * s, a * s + b * c])
    return output

