import math

def swiglu(gate, up):
    return [(g / (1 + math.exp(-g))) * u for g, u in zip(gate, up)]

top-p-sampling:
def top_p_indices(probabilities, p):
    order = sorted(range(len(probabilities)), key=lambda i: (-probabilities[i], i))
    selected, cumulative = [], 0.0
    for index in order:
        selected.append(index)
        cumulative += probabilities[index]
        if cumulative >= p:
            break
    return selected

