def residual_block(x, attention_update, ffn_update):
    if not (len(x) == len(attention_update) == len(ffn_update)):
        raise ValueError("shape mismatch")
    hidden = [a + b for a, b in zip(x, attention_update)]
    return [a + b for a, b in zip(hidden, ffn_update)]
